export async function GET() {
  try {
    const course = await prisma.course.findFirst({
      where: { title: "Web Development Basics" },
    });

    if (!course) {
      return NextResponse.json({ error: "Course not found. Ensure the initial seed was run." }, { status: 404 });
    }

    const modulesData = [
      {
        weekNumber: 1,
        title: "HTML Fundamentals",
        description: "Learn the core structure of the web.",
        topics: htmlTopics,
      },
      {
        weekNumber: 2,
        title: "CSS Styling",
        description: "Make your websites look beautiful with CSS.",
        topics: cssTopics,
      },
      {
        weekNumber: 3,
        title: "JavaScript Basics",
        description: "Add interactivity and logic to your pages.",
        topics: jsTopics,
      },
      {
        weekNumber: 4,
        title: "Final Project",
        description: "Build a complete real-world project.",
        topics: finalProjectTopics,
      },
    ];

    for (const mod of modulesData) {
      let week = await prisma.courseWeek.findFirst({
        where: { courseId: course.id, weekNumber: mod.weekNumber },
      });

      if (!week) {
        week = await prisma.courseWeek.create({
          data: {
            courseId: course.id,
            weekNumber: mod.weekNumber,
            title: mod.title,
            description: mod.description,
            topics: mod.topics,
          },
        });
      } else {
        week = await prisma.courseWeek.update({
          where: { id: week.id },
          data: {
            title: mod.title,
            description: mod.description,
            topics: mod.topics,
          }
        });
      }
    }

    return NextResponse.json({ success: true, message: "Course topics have been perfectly seeded with the new structured format!" });
  } catch (error) {
    console.error("Seed error:", error);
    return NextResponse.json({ error: "Failed to seed topics" }, { status: 500 });
  }
}
